# Register model for round 4 with corrected call
model_code = """
import numpy as np
import pandas as pd

def activation(driver):
    initial_region_max = 6.0
    activation_end = 10.0
    if driver <= initial_region_max:
        return 0.0
    elif driver >= activation_end:
        return 1.0
    else:
        t = (driver - initial_region_max) / (activation_end - initial_region_max)
        return t**2 * (3 - 2*t)

def base_sd(driver, noise_base=0.65, noise_high_slope=0.22):
    return noise_base + noise_high_slope * max(driver - 5, 0)

def model(regime, n, seed):
    np.random.seed(seed)
    line = regime.config.get('line')
    driver = regime.config.get('driver')
    # Admissible triplets and weights
    triplets = [(11.5, 3.4, 2.25), (11.5, 3.8, 2.0)]
    weights = [0.5987108427646576, 0.40128915723534236]
    scenario_probs = {'maintain': 0.84, 'revise': 0.08, 'doubt': 0.08}
    scenario_names = list(scenario_probs.keys())
    scenario_probs_arr = list(scenario_probs.values())

    idx_triplet = np.random.choice(len(triplets), size=n, p=weights)
    idx_scenario = np.random.choice(len(scenario_names), size=n, p=scenario_probs_arr)

    outcomes = []
    for i in range(n):
        gain, scale, ampl = triplets[idx_triplet[i]]
        scenario = scenario_names[idx_scenario[i]]
        mean_base = 10 + gain * (1 - np.exp(-driver / scale))
        sd = base_sd(driver)
        phi = activation(driver)
        if line == 2:
            if scenario == 'maintain':
                mean = mean_base
            elif scenario == 'revise':
                mean = mean_base - ampl * phi
            else:  # doubt
                s = np.random.choice([-1, 1])
                mean = mean_base + s * ampl * phi
        else:
            mean = mean_base
        outcomes.append(np.random.normal(mean, sd))
    return pd.DataFrame({'outcome': outcomes})
"""
env.register_model(model_code)
