final_code = """
import numpy as np
import pandas as pd

def activation(driver):
    initial_region_max = 6.0
    activation_end = 10.0
    if driver <= initial_region_max:
        return 0.0
    elif driver >= activation_end:
        return 1.0
    else:
        t = (driver - initial_region_max) / (activation_end - initial_region_max)
        return t**2 * (3 - 2*t)

def base_sd(driver, noise_base=0.65, noise_high_slope=0.22):
    return noise_base + noise_high_slope * max(driver - 5, 0)

def model(regime, n, seed):
    np.random.seed(seed)
    line = regime.config.get('line')
    driver = regime.config.get('driver')
    # Known parameters from evidence
    gain = 11.5
    scale = 3.8
    ampl = 2.0
    scenario = 'revise'  # certain
    mean_base = 10 + gain * (1 - np.exp(-driver / scale))
    sd = base_sd(driver)
    phi = activation(driver)
    if line == 2:
        # revise scenario
        mean = mean_base - ampl * phi
    else:
        mean = mean_base
    outcomes = np.random.normal(mean, sd, n)
    return pd.DataFrame({'outcome': outcomes})
"""
